params.fn:
function(){
  var loginVisible=!!document.querySelector('.login-container,[class*="login-mask"],.qrcode-img');
  var body=(document.body&&document.body.innerText)||'';
  if(body.indexOf('扫码登录')>=0)loginVisible=true;
  var profile=document.querySelector('a.link-wrapper[href*="/user/profile/"],.main-container .user a[href*="/user/profile/"]');
  var riskCaptcha=!!document.querySelector('.captcha-container')||body.indexOf('请完成下方验证')>=0;
  var loggedIn=!!profile&&!loginVisible&&!riskCaptcha;
  var nickname='';
  if(profile){
    var ch=profile.querySelector('.channel')||profile;
    nickname=(ch.textContent||'').trim();
  }
  if(nickname==='我'||nickname==='登录')nickname='';
  return {
    logged_in:loggedIn,
    login_prompt_visible:loginVisible,
    risk_captcha_visible:riskCaptcha,
    nickname:nickname,
    page_url:location.href
  };
}
